            modelBuilder.Entity("RetroFit.Domain.Entiteti.IstaknutiOglas", b =>
                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("int");

                    SqlServerPropertyBuilderExtensions.UseIdentityColumn(b.Property<int>("Id"));

                    b.Property<DateTime>("KrajUtc")
                        .HasColumnType("datetime2(3)");

                    b.Property<DateTime>("KreiranoUtc")
                        .HasColumnType("datetime2(3)");

                    b.Property<int>("KreiraoKorisnikId")
                        .HasColumnType("int");

                    b.Property<int>("OglasId")
                        .HasColumnType("int");

                    b.Property<DateTime?>("OtkazanoUtc")
                        .HasColumnType("datetime2(3)");

                    b.Property<int?>("PlacanjeId")
                        .HasColumnType("int");

                    b.Property<DateTime>("PocetakUtc")
                        .HasColumnType("datetime2(3)");

                    b.Property<string>("Tip")
                        .IsRequired()
                        .HasMaxLength(30)
                        .IsUnicode(false)
                        .HasColumnType("varchar(30)");

                    b.HasKey("Id");

                    b.HasIndex("KreiraoKorisnikId");

                    b.HasIndex("OglasId")
                        .HasDatabaseName("IX_IstaknutiOglasi_OglasId");

                    b.HasIndex("PlacanjeId")
                        .IsUnique()
                        .HasDatabaseName("UX_IstaknutiOglasi_PlacanjeId")
                        .HasFilter("[PlacanjeId] IS NOT NULL");

                    b.HasIndex("KrajUtc", "PocetakUtc")
                        .HasDatabaseName("IX_IstaknutiOglasi_Aktivni")
                        .HasFilter("[OtkazanoUtc] IS NULL");

                    SqlServerIndexBuilderExtensions.IncludeProperties(b.HasIndex("KrajUtc", "PocetakUtc"), new[] { "OglasId", "Tip" });

                    b.ToTable("IstaknutiOglasi", null, t =>
                        {
                            t.HasCheckConstraint("CK_IstaknutiOglasi_Period", "[KrajUtc] > [PocetakUtc]");

                            t.HasCheckConstraint("CK_IstaknutiOglasi_Placanje", "([Tip] = 'Podignut' AND [PlacanjeId] IS NOT NULL) OR ([Tip] = 'Izdvojen' AND [PlacanjeId] IS NULL)");

                            t.HasCheckConstraint("CK_IstaknutiOglasi_Tip", "[Tip] IN ('Izdvojen', 'Podignut')");
                        });
                });

